1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	import { stripComments } from '../../../engine/checks/helpers/code-scanning.mjs';
3	import { FREQUENCIES } from '../../claudinite-tasks/calendar.mjs';
4	import { MODEL_FAMILIES } from '../../claudinite-tasks/model-map.mjs';
5	import { OUTCOMES, LEGACY_OUTCOMES, LEGACY_CEILINGS, OUTCOME_NO_PR, DEFAULT_AGENT_MODEL, descriptionProblem } from '../../claudinite-tasks/task-contract.mjs';
6	import { validatePreconditions, termsMap } from '../../claudinite-tasks/precondition-policy.mjs';
7	import {
8	  TASK_DECLARATION_PATH_RE, isLegacyTaskDeclarationPath, readDeclarationFields,
9	} from '../../claudinite-tasks/task-declaration-text.mjs';
10	
11	// Every scheduler task is a `tasks/<name>/task.json` carrying the declaration
12	// contract (per-project-scheduling DESIGN §1) with legal enum values. This
13	// asserts that shape statically at author time — the executor and scheduler
14	// validate the same contract at run time (task-contract.mjs), so an illegal
15	// frequency/model/outcome, or a missing field, is caught here first.
16	//
17	// RELEVANCE FIRST (engine/checks/README.md): gated on a task declaration file
18	// existing, so the check is inert on any repo without tasks. Static text over the
19	// self-contained file — a `task.json` parsed whole, the retired `task.mjs` lifted
20	// by pattern — keyed off the canonical enum lists so the legal values never drift
21	// from the runtime validator.
22	
23	// The term names the task's own `preconditions.mjs` exports, read as text: the
24	// check runs over a file listing, not a module graph, so it recognises a
25	// task-local condition by the key that defines it. A term the file computes
26	// rather than spells is not found, and its declaration reads as unknown — which
27	// is the same "write it so a reader can see it" the literal rule above states.
28	function siblingTerms(ctx, taskFile) {
29	  const text = ctx.read(taskFile.replace(/task\.(json|mjs)$/, 'preconditions.mjs'));
30	  if (text === null) return new Map();
31	  const body = stripComments(text);
32	  const start = body.indexOf('export const terms');
33	  if (start === -1) return new Map();
34	  const names = [...body.slice(start).matchAll(/^  '([^']+)':/gm)].map((m) => m[1]);
35	  return termsMap(Object.fromEntries(names.map((n) => [n, { signals: [] }])));
36	}
37	
38	// A file that only re-exports another module declares nothing of its own — a
39	// legacy-path shim left behind by a relocation is the shape. The declaration it
40	// names is scanned where it actually lives, so judging the shim would report the
41	// same task twice and fail it on text it does not carry.
42	const isReExport = (text) => {
43	  const code = text.split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('//'));
44	  return code.length > 0 && code.every((l) => /^(import|export)\b.*\bfrom\b/.test(l) || /^import\s+['"]/.test(l));
45	};
46	
47	const rule = {
48	  id: 'task-declaration-shape',
49	  severity: 'blocking',
50	  description: 'A tasks/<name>/task.json carries the task contract (id, description, frequency, expected_outcome) with legal enum values and a well-formed precondition expression; an agentic task names its worker file and bounds its run, and any code_work carries a timeout and stays task-local',
51	  doc: 'packs/claudinite-tasks/README.md',
52	  why: 'the scheduler run and executor read agent_model/expected_outcome/frequency from this file, not the work item — an illegal or missing value means a task never fires, fires wrong, or writes past its ceiling',
53	
54	  run(ctx) {
55	    const out = [];
56	    for (const file of ctx.files.filter((f) => TASK_DECLARATION_PATH_RE.test(f))) {
57	      const text = ctx.read(file);
58	      if (text === null) continue;
59	      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
60	      const advise = (what, fix) => out.push(finding(rule, { file, severity: 'advisory', what, fix }));
61	
62	      const legacy = isLegacyTaskDeclarationPath(file);
63	      if (legacy) {
64	        if (isReExport(text)) continue;
65	        // ADVISORY, like every other retired spelling here: the runtime still loads
66	        // the module form, and a member's vendor refresh must not turn its CI red
67	        // over a file nothing has converted yet. The nightly update converts a
68	        // member's own; this finding names the edit for anyone editing sooner.
69	        advise('is a task.mjs, the retired module form of a task declaration',
70	          'convert it to task.json — node <engine>/migrations/task-declarations-to-json.mjs rewrites every task.mjs under the repo\'s packs and deletes the module');
71	        if (!/export\s+default\s*\{/.test(text)) {
72	          flag('does not default-export a declaration object', 'convert it to a task.json carrying { id, frequency, preconditions, expected_outcome, … }');
73	          continue;
74	        }
75	      }
76	      const decl = readDeclarationFields(file, legacy ? stripComments(text) : text);
77	      if (decl.error) {
78	        flag(`is not a JSON object: ${decl.error}`, 'write one JSON object: { "id", "frequency", "preconditions", "expected_outcome", … }');
79	        continue;
80	      }
81	      const str = (key) => (typeof decl.scalar(key) === 'string' ? decl.scalar(key) : null);
82	      const hasNum = (...keys) => keys.some((key) => typeof decl.scalar(key) === 'number');
83	
84	      const enumField = (key, legal) => {
85	        const v = str(key);
86	        if (v === null) flag(`declares no "${key}"`, `add "${key}": one of ${legal.join(', ')}`);
87	        else if (!legal.includes(v)) flag(`"${key}" is "${v}", not a legal value`, `use one of: ${legal.join(', ')}`);
88	      };
89	      enumField('frequency', FREQUENCIES);
90	      // agent_model is OPTIONAL: absent means no agent (task-defaults.mjs), so the
91	      // checks below judge the model the task will actually run at.
92	      const declaredModel = str('agent_model');
93	      if (decl.has('agent_model') && (declaredModel === null || !MODEL_FAMILIES.includes(declaredModel))) {
94	        flag(`"agent_model" is ${JSON.stringify(decl.scalar('agent_model') ?? null)}, not a legal value`, `use one of: ${MODEL_FAMILIES.join(', ')} — or drop it: a task with no agent_model runs no agent`);
95	      }
96	      const model = declaredModel ?? DEFAULT_AGENT_MODEL;
97	
98	      // expected_outcome takes the ceiling/policy split, with the retired
99	      // one-word ceilings an ADVISORY rename like the code-work names below:
100	      // the runtime normalizes them at the door forever, so a member's vendor
101	      // refresh must not turn its CI red over a declaration nobody edited.
102	      const outcome = str('expected_outcome');
103	      const hasMayAutomerge = decl.has('automerge');
104	      if (outcome === null) {
105	        flag('declares no "expected_outcome"', `add "expected_outcome": one of ${OUTCOMES.join(', ')}`);
106	      } else if (LEGACY_OUTCOMES[outcome] !== undefined) {
107	        advise(`declares the legacy outcome ceiling "${outcome}"`,
108	          `write the pair it normalizes to: "expected_outcome": "fresh_pr", "automerge": "${LEGACY_OUTCOMES[outcome]}" — and consider a narrower policy than "${LEGACY_OUTCOMES[outcome]}" (a list of diff classes, e.g. ["comment-only-changes"])`);
109	      } else if (LEGACY_CEILINGS[outcome] !== undefined) {
110	        advise(`declares the legacy outcome ceiling "${outcome}"`,
111	          `write the word it became: "expected_outcome": "${LEGACY_CEILINGS[outcome]}" — the same behaviour, in the vocabulary that also offers amend_existing_or_create_new_pr and supersede_existing_pr`);
112	      } else if (!OUTCOMES.includes(outcome)) {
113	        flag(`"expected_outcome" is "${outcome}", not a legal value`, `use one of: ${OUTCOMES.join(', ')}`);
114	      }
