1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	import { stripComments } from '../../../engine/checks/helpers/code-scanning.mjs';
3	
4	// The other half of the task contract (the writing-tasks skill, "Every task
5	// declaration carries the full contract" + "The task folder"): the declaration
6	// and the folder it sits in must AGREE. `task-declaration-shape` asserts the
7	// declaration's own shape — that `id` is present and the enums are legal — and
8	// stops at the file's edge; this rule is the cross-artifact invariant between
9	// that file and the tree around it.
10	//
11	// Why it is its own rule rather than more of that one: both faces fail the same
12	// way, and it is the way a shape error does NOT fail. Discovery
13	// (packs/claudinite-tasks/discover.mjs) is fail-soft per task — a task whose declared
14	// `id` differs from its directory name is dropped into `errors` and simply never
15	// runs, and a dangling `agent_instructions` hands the executor a worker doc that
16	// isn't there. Nothing goes red; the scheduler keeps reporting healthy runs while
17	// the task is silently absent from every one of them. That is the class this
18	// repo's own canon names as the expensive one, so it is worth catching where it
19	// is cheap: at author time, in the session that wrote the file.
20	//
21	// RELEVANCE FIRST (engine/checks/README.md): gated on a `tasks/<name>/task.json`
22	// (or the retired `task.mjs`) existing, so the rule is inert on any repo that
23	// schedules nothing. Static text over the self-contained file, the same read the
24	// shape rule uses, so the two views of one file can't disagree.
25	const TASK_DECLARATION = /(^|\/)tasks\/([^/]+)\/task\.(json|mjs)$/;
26	
27	// The value of a top-level string field, or null if absent — a `task.json`
28	// parsed whole, a `task.mjs` lifted by pattern over comment-stripped source.
29	function stringFields(file, text) {
30	  if (file.endsWith('.json')) {
31	    try {
32	      const obj = JSON.parse(text);
33	      return (key) => (obj && typeof obj[key] === 'string' ? obj[key] : null);
34	    } catch {
35	      return () => null;
36	    }
37	  }
38	  const code = stripComments(text);
39	  return (key) => {
40	    const m = new RegExp(`(?:^|[{,])\\s*${key}:\\s*['"]([^'"]+)['"]`, 'm').exec(code);
41	    return m ? m[1] : null;
42	  };
43	}
44	
45	const rule = {
46	  id: 'task-declaration-matches-folder',
47	  severity: 'blocking',
48	  description: "A tasks/<name>/task.json declares the id of its own directory, and its agent_instructions names a worker file that exists beside it",
49	  doc: 'packs/claudinite-growth/skills/writing-tasks/SKILL.md',
50	  why: 'task discovery is fail-soft per task — a declaration that disagrees with its folder is dropped into errors and the task silently never runs, while every scheduler run keeps reporting healthy',
51	
52	  run(ctx) {
53	    const out = [];
54	    for (const file of ctx.files) {
55	      const m = TASK_DECLARATION.exec(file);
56	      if (!m) continue;
57	      const dirName = m[2];
