1	// The dashboard's derivation layer — repo facts in, view rows out. Pure: it reads
2	// no clock, opens no socket, and touches no DOM, so the whole of what the page
3	// claims is testable in Node and shared verbatim with the browser.
4	//
5	// It states NONE of the queue's vocabulary itself. The label set, the title
6	// grammar, the leash constants and the anchor arithmetic are imported from the
7	// engine modules that define them, which is what makes a dashboard that cannot
8	// drift from the mechanism it renders: there is no second copy to drift.
9	//
10	// Those engine modules are pure ESM with no `node:` imports, which is the property
11	// this file depends on and `browser-graph.test.mjs` pins across the page's whole
12	// import graph. Living inside `packs/claudinite-tasks/` makes the queue modules siblings,
13	// so the dashboard sits beside the mechanism it renders rather than reaching across
14	// the tree at it.
15	//
16	// `stripComments` is the one remaining cross-tree reach, and it is deliberate:
17	// `file-placement` flags it advisory and its own remedy sanctions exactly this case.
18	// Shortening it would mean copying a comment-stripper nearer, and a second stripper
19	// that drifts from the canonical one is worse than the distance.
20	
21	import { stripComments } from '../../engine/checks/helpers/code-scanning.mjs';
22	import { parseTaskDeclaration, applyTaskDefaults } from '../claudinite-tasks/shared-code/task-declaration.mjs';
23	import { mostRecentAnchor, nextAnchor, periodMs } from '../claudinite-tasks/shared-code/anchors.mjs';
24	import {
25	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STALE_READY_PERIODS, STUCK_BLOCKED_MS,
26	} from '../claudinite-tasks/shared-code/work-items.mjs';
27	import {
28	  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT,
29	  outcomeOf as decodeOutcome,
30	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
31	  statusesOn, isParked, parkKindOf, triageLabelFor,
32	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_APPROVAL,
33	  NEEDS_HUMAN_FAILURE, isBlockingPark, parseLastVerdict,
34	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
35	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, hasLabel, labelNames,
36	} from '../claudinite-tasks/shared-code/work-items.mjs';
37	
38	export {
39	  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT,
40	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STUCK_BLOCKED_MS, STALE_READY_PERIODS,
41	  parseWorkItemTitle, nextAnchor, mostRecentAnchor, periodMs,
42	};
43	
44	// How long a due item may sit blocked before the page calls the scheduler run out. The scheduler run
45	// is the repo's one cron, hourly; two fires of slack keeps a single late fire from
46	// reading as a fault. Not an engine constant because nothing engine-side measures
47	// this — the scheduler run readies due items on its next fire, whenever that is.
48	export const DUE_SLACK_MS = 2 * 3600e3;
49	
50	const ms = (t) => (t == null ? null : new Date(t).getTime());
51	
52	// --- where a declared pack's tasks live ---------------------------------------
53	
54	// A pack contributes tasks only if the repo DECLARES it: presence on disk is not
55	// activation (core's rule), and the mount carries packs a repo never declared. So
56	// the roster is built from the declaration list, and a task directory belonging to
57	// an undeclared pack is skipped rather than rendered greyed-out.
58	//
59	// Two roots, because the same code reads the canon home and a member: the home
60	// runs from the repo root (`packs/<id>`), a member from the mount
61	// (`.claudinite/shared/packs/<id>`), and a local pack — declared `local/<name>` —
62	// from `.claudinite/local/packs/<name>` in both.
63	export function declaredPackDirs(config) {
64	  const dirs = new Map();
65	  for (const entry of config?.packs ?? []) {
66	    const id = typeof entry === 'string' ? entry : entry?.id;
67	    if (!id) continue;
68	    if (id.startsWith('local/')) {
69	      const name = id.slice('local/'.length);
70	      dirs.set(id, [`.claudinite/local/packs/${name}`]);
71	    } else {
72	      dirs.set(id, [`packs/${id}`, `.claudinite/shared/packs/${id}`]);
73	    }
74	  }
75	  return dirs;
76	}
77	
78	const TASK_PATH_RE = /^(.*)\/tasks\/([^/]+)\/task\.(json|mjs)$/;
79	
80	// Every declared pack's task declarations, from one recursive tree listing.
81	// `paths` is the flat list of blob paths the tree API returned.
82	export function taskDeclarationPaths(paths, config) {
83	  const dirs = declaredPackDirs(config);
84	  const found = [];
85	  for (const path of paths ?? []) {
86	    const m = TASK_PATH_RE.exec(path);
87	    if (!m) continue;
88	    const [, packDir, task] = m;
89	    for (const [pack, roots] of dirs) {
90	      if (roots.includes(packDir)) found.push({ pack, task, path });
91	    }
92	  }
93	  return found.sort((a, b) => `${a.pack}/${a.task}`.localeCompare(`${b.pack}/${b.task}`));
94	}
95	
96	// --- reading a task declaration -----------------------------------------------
97	
98	// The page reads a declaration as TEXT: it renders other repos over the API, where
99	// there is nothing to import and no Node to import it with. A `task.json` parses
100	// whole and takes the contract's defaults for the fields it omits — the same
101	// door the engine's loader runs it through. The retired `task.mjs` is a JS
102	// object literal, so its scalar fields are lifted by pattern over comment-stripped
103	// source — the engine's own `stripComments`, so a `// frequency: 'weekly'` in a
104	// task's header prose can never be mistaken for the declaration.
105	//
106	// A field this cannot read comes back NULL and renders as "unknown". It is never
107	// defaulted: a task whose declaration this misreads must look unreadable, because a
108	// plausible wrong frequency would silently move a next-anchor the whole roster is
109	// read for.
110	// The key must open the line or follow a `{` / `,` — anchoring on the line start
111	// alone would miss a declaration written on one line, and anchoring on nothing
112	// would let `code_work` be found inside `agent_code_work`. The value may close on a
113	// comma, the object's brace, or the line's end, so a last field without a trailing
114	// comma still reads.
115	const at = (field) => `(?:^|[{,])\\s*${field}:\\s*`;
116	
117	const scalar = (src, field) => {
118	  const m = new RegExp(`${at(field)}(?:'([^']*)'|"([^"]*)"|(\\d+)|(true|false))\\s*(?=[,}\\n]|$)`, 'm').exec(src);
119	  if (!m) return null;
120	  if (m[3] !== undefined) return Number(m[3]);
121	  if (m[4] !== undefined) return m[4] === 'true';
122	  return m[1] ?? m[2];
123	};
124	
125	const stringArray = (src, field) => {
126	  const m = new RegExp(`${at(field)}\\[([^\\]]*)\\]`, 'm').exec(src);
127	  if (!m) return null;
128	  return [...m[1].matchAll(/'([^']*)'|"([^"]*)"/g)].map((x) => x[1] ?? x[2]);
129	};
130	
131	export function parseDeclaration(text, path = '') {
132	  if (path.endsWith('.json') || /^\s*\{/.test(String(text ?? ''))) return parseJsonDeclaration(text);
133	  const src = stripComments(String(text ?? ''));
134	  return {
135	    id: scalar(src, 'id'),
136	    frequency: scalar(src, 'frequency'),
137	    agent_model: scalar(src, 'agent_model'),
138	    expected_outcome: scalar(src, 'expected_outcome'),
139	    interrupt_policy: scalar(src, 'interrupt_policy'),
140	    code_work: scalar(src, 'code_work'),
141	    agent_execution_timeout: scalar(src, 'agent_execution_timeout'),
142	    // The conditions a task declares. One form, and only one (#1617): the
143	    // `preconditions` expression. A member still stamping the retired
144	    // `precondition_signals` reads as no conditions here, which is what it is —
145	    // a declaration the current engine does not accept.
146	    preconditions: stringArray(src, 'preconditions'),
147	    // A task may decline to run; whether it CAN is the difference between "did not
148	    // run" being routine and being a fault, so the roster shows it. `['none']` is
149	    // the EMPTY precondition and answers no here, exactly as a task with no gate at
150	    // all does — which is what it means.
151	    has_precondition: (stringArray(src, 'preconditions') ?? []).some((c) => c !== 'none'),
152	  };
153	}
154	
155	// The JSON form. The fields the roster reads, and only those, so a declaration
156	// carrying more renders the same as one carrying exactly these. Unparseable text
157	// reads as every field unknown, the same face the module form shows.
158	function parseJsonDeclaration(text) {
159	  let decl;
160	  try {
161	    decl = parseTaskDeclaration(String(text ?? ''));
162	    if (decl !== null && typeof decl === 'object' && !Array.isArray(decl)) applyTaskDefaults(decl);
163	  } catch {
164	    decl = null;
165	  }
166	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) decl = {};
167	  const scalarOf = (v) => (['string', 'number', 'boolean'].includes(typeof v) ? v : null);
168	  const preconditions = Array.isArray(decl.preconditions) && decl.preconditions.every((c) => typeof c === 'string') ? decl.preconditions : null;
169	  return {
170	    id: scalarOf(decl.id),
171	    frequency: scalarOf(decl.frequency),
172	    agent_model: scalarOf(decl.agent_model),
173	    expected_outcome: scalarOf(decl.expected_outcome),
174	    interrupt_policy: scalarOf(decl.interrupt_policy),
175	    code_work: scalarOf(decl.code_work),
176	    agent_execution_timeout: scalarOf(decl.agent_execution_timeout),
177	    preconditions,
178	    has_precondition: (preconditions ?? []).some((c) => c !== 'none'),
179	  };
180	}
181	
182	// --- work items ----------------------------------------------------------------
183	
184	// An item is a filed `[claudinite-work]` issue OR an adopted marked issue — the
185	// one-issue request model's other shape, which keeps the person's own title
186	// (tasks-dispatch DESIGN §16.1). One definition, shared with the queue's own reader.
187	export { isQueueItem as isWorkItem } from '../claudinite-tasks/shared-code/work-items.mjs';
188	
189	// THE PAGE'S FIVE STATE KEYS. Four are the engine's own status labels; the fifth is
190	// this page's own word, because a park is four labels and the page groups them into
191	// one column, routing by kind separately (`triageOf`). It is a display key and never
192	// a label: nothing writes `parked` to an issue.
193	const STATE_KEY = new Map([
194	  [STATUS_BLOCKED, BLOCKED], [STATUS_READY, READY],
195	  [STATUS_RUNNING_EXECUTOR, EXECUTING], [STATUS_RUNNING_AGENT, AGENT],
196	]);
197	
198	// The one state an open item is in, decoded from whatever spelling filed it, or
199	// `unlabelled` for an item wearing none — which is not a display quirk but the
200	// torn-label-swap leavings the janitor repairs, so it gets its own rendered state
201	// rather than being folded into "blocked".
202	export const PARKED = 'parked';
203	
204	export function stateOf(item) {
205	  if (item?.state === 'closed') return 'closed';
206	  if (isParked(item)) return PARKED;
207	  const worn = statusesOn(item).filter((s) => STATE_KEY.has(s));
208	  if (worn.length === 1) return STATE_KEY.get(worn[0]);
209	  if (worn.length > 1) return 'torn';
210	  return 'unlabelled';
211	}
212	
213	// What the park is asking for, or null for an item that is not parked. A park whose
214	// kind cannot be decoded — an older engine's bare one, a word a newer engine
215	// invented — reads as `failure`, the lane that says "someone diagnose this".
216	export const triageOf = (item) => (isParked(item) ? triageLabelFor(parkKindOf(item)) : null);
217	
218	const TRIAGE_TEXT = {
219	  [NEEDS_HUMAN_APPROVAL]: 'a PR to approve',
220	  [NEEDS_HUMAN_ACTION]: 'something to change outside the code',
221	  [NEEDS_HUMAN_DECISION]: 'a decision to make',
222	  [NEEDS_HUMAN_FAILURE]: 'a break to diagnose, holding the task\'s lane',
223	};
224	
225	// The outcome as its canonical word ('done' | 'delivered' | 'obsolete' | null) —
226	// the engine's decoder, which maps every legacy spelling straight to today's.
227	export const outcomeOf = decodeOutcome;
228	
229	// How long the item has sat where it is. Every transition is a label write, so
230	// `updated_at` is the last touch — the same quantity the janitor's rules count.
231	const idleMs = (item, now) => ms(now) - (ms(item?.updated_at) ?? ms(item?.created_at) ?? ms(now));
232	
233	// Warnings, each mirroring a real recovery rule rather than a display heuristic, so
234	// what the page flags is what the engine will actually act on — and how long the
235	// viewer waits for it.
236	//
237	// `isOpen(number)` answers whether a `Blocked-by` issue is still open — true, false,
238	// or null for one outside what the caller fetched. Unknown is never alarmed on.
239	export function warningsFor(item, now, { periodFor = () => null, isOpen = () => null } = {}) {
240	  const out = [];
241	  const state = stateOf(item);
242	  const idle = idleMs(item, now);
243	  if (state === EXECUTING && idle >= EXECUTING_LEASH_MS) {
244	    out.push({ level: 'serious', text: 'executing past the leash — the next scheduler run reclaims it' });
245	  }
246	  if (state === AGENT && idle >= AGENT_LEASH_MS) {
247	    out.push({ level: 'serious', text: 'agent claim past the leash — the janitor reclaims it' });
248	  }
249	  if (state === READY) {
250	    const per = periodFor(`${parseWorkItemTitle(item.title)?.pack}/${parseWorkItemTitle(item.title)?.task}`) ?? 86400e3;
251	    if (idle >= STALE_READY_PERIODS * per) out.push({ level: 'serious', text: 'ready but unpicked for ~2 periods' });
252	  }
253	  if (state === BLOCKED) {
254	    // The standing-item model: blocked is the queue's healthy quiet state, not a
255	    // fault. A rolled item waiting out its Not-before never warns; what does warn is
256	    // the two things the engine would actually act on — dependencies unresolved past
257	    // the janitor's threshold, and an item DUE that the scheduler run has failed to ready.
258	    const { notBefore, blockedBy } = parseWorkItemBody(item.body);
259	    const wake = ms(notBefore);
260	    const depStates = blockedBy.map((n) => isOpen(n));
261	    if (wake !== null && wake > ms(now)) {
262	      // waiting out its stamped wake — healthy, whatever its age
263	    } else if (depStates.some((s) => s === true)) {
264	      if (idle >= STUCK_BLOCKED_MS) {
265	        out.push({ level: 'warning', text: `blocked on ${blockedBy.map((n) => `#${n}`).join(', ')} for over 2 days — the janitor flags stuck dependencies` });
266	      }
267	    } else if (!depStates.some((s) => s === null)) {
268	      // Nothing blocks it any more: the next scheduler run readies it. Due only measures from
269	      // the stamped wake — with dependencies the closing time is not on this item,
270	      // and a guess would alarm on an item that became due minutes ago.
271	      if (wake !== null && ms(now) - wake >= DUE_SLACK_MS) {
272	        out.push({ level: 'serious', text: 'due but not readied — is the scheduler run running?' });
273	      } else if (wake === null && blockedBy.length === 0 && idle >= DUE_SLACK_MS) {
274	        out.push({ level: 'serious', text: 'due but not readied — is the scheduler run running?' });
275	      }
276	    }
277	  }
278	  if (state === PARKED) {
279	    // What the park is asking for, and whether it is holding the task's lane —
280	    // an approval waiting on a reviewer is not the same alarm as a broken run
281	    // that has stopped its task being scheduled at all.
282	    const t = triageOf(item);
283	    out.push({
284	      level: isBlockingPark(item) ? 'critical' : 'warning',
285	      text: t ? `parked for a human — ${TRIAGE_TEXT[t]}` : 'parked for a human — unclassified, holding the task\'s lane',
286	    });
287	  }
288	  if (state === 'torn') out.push({ level: 'warning', text: 'wearing more than one state label' });
289	  if (state === 'unlabelled') out.push({ level: 'warning', text: 'open with no state label' });
290	  return out;
291	}
292	
293	// An open item, decorated with everything the queue lane renders.
294	export function describeItem(item, now, opts = {}) {
295	  // A marked issue keeps the person's own title, so its task comes from the worker
296	  // path its machine block names — without that the page would render every request
297	  // run as an item belonging to no task at all.
298	  const parsed = parseWorkItemTitle(item.title)
299	    ?? (taskIdFromPath(parseWorkItemBody(item.body).taskPath) ? { ...taskIdFromPath(parseWorkItemBody(item.body).taskPath), qualifier: null } : null)
300	    ?? { pack: null, task: null, qualifier: null };
301	  const body = parseWorkItemBody(item.body);
302	  const state = stateOf(item);
303	  return {
304	    number: item.number,
305	    // The issue's own title, kept as GitHub has it: a surface that NAMES one item —
306	    // rather than counting them — has nothing else to call it by.
307	    title: item.title,
308	    key: parsed.pack && parsed.task ? `${parsed.pack}/${parsed.task}` : null,
309	    ...parsed,
310	    state,
311	    outcome: outcomeOf(item),
312	    triage: triageOf(item),
313	    blockingPark: state === PARKED && isBlockingPark(item),
314	    urgent: hasLabel(item, URGENT),
315	    labels: labelNames(item),
316	    notBefore: body.notBefore,
317	    blockedBy: body.blockedBy,
318	    taskPath: body.taskPath,
319	    // The roll's record: when the last ask declined, why, and the stamped wake.
320	    lastVerdict: parseLastVerdict(item.body),
321	    createdAt: item.created_at,
322	    updatedAt: item.updated_at,
323	    closedAt: item.closed_at ?? null,
324	    idleMs: idleMs(item, now),
325	    comments: item.comments ?? 0,
326	    warnings: warningsFor(item, now, opts),
327	  };
328	}
329	
330	// --- the roster ----------------------------------------------------------------
331	
332	// One row per DECLARED task, whether or not it has ever run — a task that has never
333	// produced an item is exactly the interesting case, and an issue-derived list would
334	// omit it entirely.
335	export function buildRoster({ tasks = [], items = [], now, schedule, isOpen }) {
336	  const byKey = new Map();
337	  for (const it of items) {
338	    const p = parseWorkItemTitle(it.title);
339	    if (!p) continue;
340	    const key = `${p.pack}/${p.task}`;
341	    if (!byKey.has(key)) byKey.set(key, []);
342	    byKey.get(key).push(it);
343	  }
344	
345	  return tasks.map((t) => {
346	    const key = `${t.pack}/${t.task}`;
347	    const mine = (byKey.get(key) ?? []).slice()
348	      .sort((a, b) => ms(b.created_at) - ms(a.created_at));
349	    const open = mine.filter((i) => i.state === 'open');
350	    const closed = mine.filter((i) => i.state === 'closed');
351	    const freq = t.declaration?.frequency ?? null;
352	
353	    // A frequency this could not read yields no anchor rather than a guessed one,
354	    // and `manual` genuinely has none — the two are different and render differently.
355	    let next = null;
356	    let anchorNote = null;
357	    if (freq === 'manual') anchorNote = 'manual — only a hand-created item';
358	    else if (!freq) anchorNote = 'frequency unknown';
359	    else if (!schedule) anchorNote = 'no schedule configured';
360	    else next = nextAnchor(freq, schedule, now);
361	
362	    const current = open.length
363	      ? describeItem(open[0], now, { periodFor: () => (freq ? periodMs(freq) : null), isOpen })
364	      : null;
365	
366	    return {
367	      key,
368	      pack: t.pack,
369	      task: t.task,
370	      path: t.path,
371	      declaration: t.declaration ?? null,
372	      frequency: freq,
373	      nextAnchor: next,
374	      anchorNote,
375	      periodMs: freq && freq !== 'manual' ? periodMs(freq) : null,
376	      current,
377	      nextAsk: nextAskOf(current, next, anchorNote),
378	      openCount: open.length,
379	      lastClosed: closed.length ? describeItem(closed[0], now) : null,
380	      history: closed.map((i) => describeItem(i, now)),
381	    };
382	  });
383	}
384	
385	// What will actually happen to this task next, derived from the standing item where
386	// one exists — the calendar answers only when no item does (the next instantiation).
387	// This is where the standing-item model's facts become the roster's advice:
388	//   - the stamped Not-before IS the schedule (DESIGN §14, S28), so it wins over the
389	//     computed anchor;
390	//   - a blocking park stops the task being scheduled at all (§4) — showing an anchor
391	//     there would promise a run that will never be filed;
392	//   - a non-blocking park consumed its occurrence but leaves the lane open, so the
393	//     next anchor stands beside it.
394	function nextAskOf(current, anchor, anchorNote) {
395	  if (!current) return anchor ? { kind: 'anchor', at: anchor } : { kind: 'note', note: anchorNote };
396	  if (current.state === READY) return { kind: 'ready', urgent: current.urgent };
397	  if (current.state === EXECUTING || current.state === AGENT) {
398	    return { kind: 'running', phase: current.state === AGENT ? 'agent' : 'executor' };
399	  }
400	  if (current.state === PARKED) {
401	    if (current.blockingPark) return { kind: 'held' };
402	    return anchor ? { kind: 'anchor', at: anchor } : { kind: 'note', note: anchorNote };
403	  }
404	  if (current.state === BLOCKED) {
405	    if (current.notBefore) return { kind: 'wake', at: new Date(current.notBefore) };
406	    return current.blockedBy.length ? { kind: 'deps', on: current.blockedBy } : { kind: 'ready-soon' };
407	  }
408	  // torn / unlabelled — off the state machine until the janitor repairs it.
409	  return { kind: 'off-machine' };
410	}
411	
412	// --- what is about to happen ------------------------------------------------------
413	
414	// The next 24 hours as UTC hour buckets, each carrying the task rows whose next ask
415	// lands in it. The strip this draws answers a question no single row can: whether the
416	// day's scheduled work is spread out or piled into one hour.
417	//
418	// FLEET OR REPO, the same reduction: the caller hands in whatever roster rows it has,
419	// one member's or every member's, and a row carries the repo it came from where that
420	// matters.
421	//
422	// A `held` next ask is placed at NOW and marked critical rather than left out. A task
423	// whose blocking park stops it being scheduled at all has no future anchor, and
424	// dropping it would draw the emptiest strip on the worst-off repo — the one case where
425	// an empty hour must not read as a quiet one.
426	export const WAKE_STRIP_HOURS = 24;
427	
428	export function wakeStrip(rows, now, { hours = WAKE_STRIP_HOURS } = {}) {
429	  const start = new Date(now);
430	  start.setUTCMinutes(0, 0, 0);
431	  const key = (t) => new Date(t).toISOString().slice(0, 13);
432	  const buckets = Array.from({ length: hours }, (_, i) => ({
433	    hour: key(start.getTime() + i * 3600e3),
434	    tasks: [],
435	    held: 0,
436	  }));
437	  const byHour = new Map(buckets.map((b) => [b.hour, b]));
438	
439	  for (const row of rows ?? []) {
440	    const ask = row?.nextAsk;
441	    if (!ask) continue;
442	    const held = ask.kind === 'held';
443	    // Only the two kinds that name a MOMENT land on a strip of hours: an anchor (the
444	    // calendar's next fire) and a wake (a stamped Not-before, which IS the schedule).
445	    // `ready`, `running` and `deps` are happening or waiting on something other than
446	    // the clock, and belong to the row rather than to a future hour.
447	    const at = held ? start.getTime() : (ask.kind === 'anchor' || ask.kind === 'wake' ? ms(ask.at) : null);
448	    if (at === null) continue;
449	    const bucket = byHour.get(key(at));
450	    if (!bucket) continue;                      // past the strip's far end — not this day's business
451	    bucket.tasks.push({ key: row.key, repo: row.repo ?? null, held });
452	    if (held) bucket.held += 1;
453	  }
454	
455	  const peak = buckets.reduce((n, b) => Math.max(n, b.tasks.length), 0);
456	  return { from: buckets[0]?.hour ?? null, hours: buckets, peak };
457	}
458	
459	// Outcome tallies over the closed items the scan actually saw. `scanned` travels
460	// with them: every count here is over a window, and a window is not "all of it".
461	export function outcomeTally(rows) {
462	  const t = { done: 0, delivered: 0, obsolete: 0, none: 0 };
463	  for (const r of rows) for (const h of r.history) t[h.outcome ?? 'none'] += 1;
464	  return t;
465	}
466	
467	// --- the protocol comments ------------------------------------------------------
468	
469	// Which of the three markers a comment carries. The markers are HTML comments so a
470	// human reading the issue sees prose; the page shows the protocol beat instead.
471	export function commentKind(body) {
472	  const b = String(body ?? '');
473	  if (b.includes(EPISODE_MARKER)) return 'episode';
474	  if (b.includes(HANDOFF_MARKER)) return 'handoff';
475	  if (b.includes(CLAIM_MARKER)) return 'claim';
476	  return null;
477	}
478

