215	// --- the inline path scope (`under:<dir>`) ------------------------------------
216	
217	// A rule name that carries its own argument: `under:packs/claudinite-tasks`
218	// covers every change inside that directory. It exists because a scope is
219	// usually per-request — the one folder an ad-hoc ask or a task is confined to —
220	// where a named merge-rules.json rule is per-pack and costs a commit to add.
221	//
222	// It covers any change KIND inside the directory (added, modified, deleted):
223	// "any change under this folder" reads as literally any. And it scopes rather
224	// than widens — a changed file outside the folder is covered by no allow term,
225	// so a diff that strays parks — with POLICY_SOURCES below still absolute, so a
226	// folder scope cannot reach the files that define policies even when they sit
227	// inside it.
228	export const UNDER_PREFIX = 'under:';
229	
230	const PATH_SEGMENT_RE = /^[A-Za-z0-9._-]+$/;
231	
232	// The rule an `under:<dir>` term denotes, or null when `<dir>` is not a usable
233	// repo-relative directory (absolute, empty, or carrying a `.`/`..` segment).
234	// Null is a verdict: an unresolvable scope makes the whole policy invalid, which
235	// authorizes nothing — the same fail-closed answer an unknown rule name gets.
236	export function underRule(term) {
237	  const dir = term.slice(UNDER_PREFIX.length).replace(/\/+$/, '');
238	  const segments = dir.split('/');
239	  if (!dir || segments.some((seg) => !PATH_SEGMENT_RE.test(seg) || seg === '.' || seg === '..')) return null;
240	  const prefix = `${dir}/`;
241	  return { name: term, appliesTo: (e) => e.file.startsWith(prefix) };
242	}
243	
244	// --- the `&&` intersection ----------------------------------------------------
245	
246	// A policy list is a UNION: adding a term widens what may land. `&&` is the one
247	// narrowing operator — `under:product-wiki&&doc-changes` covers a file only when
248	// every part covers it, so it reads as "docs, and only under that folder".
249	//
250	// Whitespace around it is accepted wherever a human writes one (an issue's
251	// `Automerge:` line, a task declaration) and canonicalized away by
252	// `policyExpression`, so what rides the commit trailer stays one whitespace-free
253	// token. `&` is not a legal character in a rule name or an `under:` path, so the
254	// operator can never be read as part of a term.
255	export const CONJUNCTION = '&&';
256	
257	const conjunctionParts = (term) => term.split(CONJUNCTION).map((p) => p.trim());
258	
259	// --- pack-declared rules (merge-rules.json) -----------------------------------
260	
261	export const MERGE_RULES_FILE = 'merge-rules.json';
262	
263	const RULE_NAME_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
264	const DECLARED_KEYS = ['name', 'pathMatching', 'excludePathMatching', 'changeKinds', 'editShape', 'coversMountPolicySources'];
265	const CHANGE_KINDS = ['added', 'modified', 'deleted'];
266	const EDIT_SHAPES = ['any', 'removals-only', 'comment-only'];
267	
268	// Regex-as-string in the `/body/flags` form declared-checks.json already uses —
269	// the same inline parse pattern-rules.mjs applies (this module cannot import the
270	// checks engine's private compiler, so the six lines live here and point there).
271	function compileRegex(raw, where) {
272	  const m = /^\/(.*)\/([a-z]*)$/s.exec(String(raw));
273	  if (!m) throw new Error(`${where}: ${JSON.stringify(raw)} is not a /pattern/ regex string`);
274	  return new RegExp(m[1], m[2]);
275	}
276	
277	// One declared rule compiled into the registry shape. Every key is validated and
278	// `changeKinds`/`editShape` are REQUIRED — a matcher whose reach is defaulted is
279	// a matcher nobody decided (the corpus' explicit-over-default rule).
280	export function compileDeclaredRule(spec, where) {
281	  if (spec === null || typeof spec !== 'object' || Array.isArray(spec)) {
282	    throw new Error(`${where}: a merge rule is an object, not ${JSON.stringify(spec)}`);
283	  }
284	  for (const key of Object.keys(spec)) {
285	    if (!DECLARED_KEYS.includes(key)) {
286	      throw new Error(`${where}: "${key}" is not a merge-rule key — the vocabulary is: ${DECLARED_KEYS.join(', ')}`);
287	    }
288	  }
289	  if (typeof spec.name !== 'string' || !RULE_NAME_RE.test(spec.name)) {
290	    throw new Error(`${where}: a merge rule needs a kebab-case "name"`);
291	  }
292	  const pathMatching = compileRegex(spec.pathMatching, `${where} (${spec.name}).pathMatching`);
293	  const exclude = spec.excludePathMatching === undefined
294	    ? null : compileRegex(spec.excludePathMatching, `${where} (${spec.name}).excludePathMatching`);
295	  if (!Array.isArray(spec.changeKinds) || !spec.changeKinds.length
296	      || spec.changeKinds.some((k) => !CHANGE_KINDS.includes(k))) {
297	    throw new Error(`${where} (${spec.name}): "changeKinds" is a non-empty subset of ${CHANGE_KINDS.join(', ')}`);
298	  }
299	  if (!EDIT_SHAPES.includes(spec.editShape)) {
300	    throw new Error(`${where} (${spec.name}): "editShape" must be one of ${EDIT_SHAPES.join(', ')} — declared, never defaulted`);
301	  }
302	  // The one key that may relax the self-widening guard, and only for files under
303	  // the VENDORED MOUNT (see POLICY_SOURCES below): declaring it is an owner
304	  // saying "this task may rewrite the mount, policy definitions included" — the
305	  // adoption/converge grant. `true` only, so it cannot be half-declared.
306	  if (spec.coversMountPolicySources !== undefined && spec.coversMountPolicySources !== true) {
307	    throw new Error(`${where} (${spec.name}): "coversMountPolicySources" takes only \`true\` — omit it otherwise`);
308	  }
309	  return {
310	    name: spec.name,
311	    coversMountPolicySources: spec.coversMountPolicySources === true,
312	    appliesTo(e) {
313	      if (!pathMatching.test(e.file) || (exclude && exclude.test(e.file))) return false;
314	      if (!spec.changeKinds.includes(changeKindOf(e))) return false;
315	      if (spec.editShape === 'removals-only') return changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after);
316	      if (spec.editShape === 'comment-only') return isCommentOnlyChange(e);
317	      return true;
318	    },
319	  };
320	}
321	
322	// The merge rules the ACTIVE packs declare, keyed by name. `packs` are discovered
323	// pack objects (each with `.dir`), `config` the normalized repo config — the pair
324	// both judging surfaces already hold. A broken declaration or a name collision is
325	// an ERROR entry, never a silent drop: a policy naming the broken rule must fail
326	// closed, and the error text is what gets it fixed.
327	export function declaredMergeRules(packs, config) {
328	  const rules = new Map();
329	  const errors = [];
330	  for (const pack of (packs ?? []).filter((p) => p.dir && isActive(p, config))) {
331	    const file = path.join(pack.dir, MERGE_RULES_FILE);
332	    if (!existsSync(file)) continue;
333	    const where = `${pack.id}/${MERGE_RULES_FILE}`;
334	    let specs;
335	    try {
336	      specs = JSON.parse(readFileSync(file, 'utf8'));
337	      if (!Array.isArray(specs)) throw new Error('the file must hold an array of rule objects');
338	    } catch (e) {
339	      errors.push(`${where}: ${e.message}`);
340	      continue;
341	    }
342	    for (const spec of specs) {
343	      try {
344	        const rule = compileDeclaredRule(spec, where);
345	        if (BUILTIN_MERGE_RULES.has(rule.name) || COMPOSITE_POLICIES.has(rule.name) || rules.has(rule.name)) {
346	          throw new Error(`rule name "${rule.name}" is already taken — merge-rule names are one flat namespace`);
347	        }
348	        rules.set(rule.name, rule);
349	      } catch (e) {
350	        errors.push(e.message.startsWith(where) ? e.message : `${where}: ${e.message}`);
351	      }
352	    }
353	  }
354	  return { rules, errors };
355	}
356	
357	// --- policy parsing -----------------------------------------------------------
358	
359	const TERM_NAME_RE = /^(under:\S+|[a-z0-9]+(-[a-z0-9]+)*)$/;
360	
361	// A policy, normalized from any surface it rides — the declaration's string or
362	// array, the item's `Merge:` field, the commit trailer's `a;b;reject:c` — into
363	// { kind: 'nothing' | 'anything' } or { kind: 'rules', allow, reject } or
364	// { kind: 'invalid', reason }. Invalid is a verdict-shaped answer on purpose:
365	// every consumer treats it as "authorizes nothing", loudly.
366	export function normalizePolicy(raw) {
367	  if (raw == null) return { kind: POLICY_NOTHING };
368	  const terms = Array.isArray(raw)
369	    ? raw.map((t) => String(t).trim())
370	    : String(raw).trim().split(';').map((t) => t.trim());
371	  if (terms.length === 1) {
372	    const one = terms[0].toLowerCase();
373	    if (one === POLICY_NOTHING || one === '') return { kind: POLICY_NOTHING };
374	    if (one === POLICY_ANYTHING) return { kind: POLICY_ANYTHING };
375	    // The queue's historical spellings for its one pre-policy authorization.
376	    if (one === 'if-narrow' || one === 'yes' || one === 'true') return normalizePolicy(['narrow-diff']);
377	  }
378	  const allow = [];
379	  const reject = [];
380	  for (const term of terms) {
381	    const isReject = term.startsWith('reject:');
382	    const parts = conjunctionParts(isReject ? term.slice('reject:'.length) : term);
383	    for (const part of parts) {
384	      if (!TERM_NAME_RE.test(part)) {
385	        return { kind: 'invalid', reason: `"${term}" is not a policy term (rule names or under:<dir>, joined with && and optionally reject:-prefixed)` };
386	      }
387	      if (part.startsWith(UNDER_PREFIX) && !underRule(part)) {
388	        return { kind: 'invalid', reason: `"${part}" names no usable repo-relative directory — spell it under:packs/some-pack` };
389	      }
390	    }
391	    // A composite is itself a union, so intersecting one is ambiguous, and the
392	    // whole-policy words mean nothing narrowed: both are authoring errors.
393	    if (parts.length > 1) {
394	      const notIntersectable = parts.find((p) => COMPOSITE_POLICIES.has(p) || p === POLICY_ANYTHING || p === POLICY_NOTHING);
395	      if (notIntersectable) {
396	        return { kind: 'invalid', reason: `"${notIntersectable}" cannot sit in an && term — intersect specific rules` };
397	      }
398	    }
399	    const name = parts.join(CONJUNCTION);
400	    if (isReject) {
401	      if (COMPOSITE_POLICIES.has(name)) return { kind: 'invalid', reason: `"${term}" rejects a composite — name the specific rules to reject` };
402	      reject.push(name);
403	    } else if (name === POLICY_ANYTHING) {
404	      allow.push(name);
405	    } else if (name === POLICY_NOTHING) {
406	      return { kind: 'invalid', reason: `"nothing" cannot sit in a rule list — it is a whole policy of its own` };
407	    } else {
408	      allow.push(...(COMPOSITE_POLICIES.get(name) ?? [name]));
409	    }
410	  }
411	  if (!allow.length) {
412	    return { kind: 'invalid', reason: 'the policy lists no allow term — "anything except X" is spelled ["anything", "reject:X"]' };
413	  }
414	  return { kind: 'rules', allow: [...new Set(allow)], reject: [...new Set(reject)] };
415	}
416	
417	// The string form of a declared policy — what rides the commit trailer and the
418	// worker's CLI invocation. Inverse of normalizePolicy for every legal value, and
419	// the one place whitespace around `&&` is collapsed, which is what keeps the
420	// stamped trailer a single whitespace-free token.
421	export const policyExpression = (policy) =>
422	  (Array.isArray(policy) ? policy : String(policy ?? POLICY_NOTHING).split(';'))
423	    .map((t) => conjunctionParts(String(t).trim()).join(CONJUNCTION))
424	    .join(';');
425	
426	// --- the verdict --------------------------------------------------------------
427	
428	// The files no granular policy may cover except as comment-only edits: the
429	// sources the policy machinery itself is read from. Whatever an allow rule says,
430	// a run authorized by a list must not be able to rewrite what it is authorized
431	// to do. (`'anything'` — the vendored-converge lane — is deliberately exempt:
432	// the mount refresh replaces these files wholesale, and that lane's trust is the
433	// repo's delivery setting, not a diff class.)
434	//
435	// One narrow relaxation: such a file UNDER THE VENDORED MOUNT may be covered by
436	// a declared rule carrying `coversMountPolicySources` — the shape an adoption
437	// re-vendor has, where policy files arrive canon-authored inside the pack trees
438	// it copies. The flag rides merge-rules.json, which is itself guarded and
439	// owner-committed, so a run cannot grant it to itself; repo-owned policy
440	// sources (everything outside the mount) stay absolute.
441	const POLICY_SOURCES = /(^|\/)(merge-rules\.json|merge-policy\.mjs|workRules\/automerge-policy-scope\.mjs|tasks\/[^/]+\/task\.(json|mjs))$/;
442	const VENDORED_MOUNT = /^\.claudinite\/shared\//;
443	
444	// The whole verdict over a diff. `entries` are `{ file, before, after }` (null
445	// side = added/deleted); `declaredRules` a Map from declaredMergeRules, with its
446	// `errors` passed through so a broken declaration fails any policy that names
447	// the broken pack's rule set. Returns { mergeable, why, files, problems }:
448	// `files` carries one line per changed file (its covering rule, or its
449	// violation), `problems` each refusal as { file, what } — file null for a
450	// whole-diff refusal — because a run that parks has to say what it parked over.
451	export function policyVerdict({ policy, entries, declaredRules = new Map(), ruleErrors = [] }) {
452	  const refuse = (problems, files = []) => ({
453	    mergeable: false, why: problems.map((p) => p.what).join('; '), files, problems,
454	  });
455	  const norm = normalizePolicy(policy);
456	  if (norm.kind === 'invalid') return refuse([{ file: null, what: `invalid policy: ${norm.reason}` }]);
457	  if (norm.kind === POLICY_NOTHING) {
458	    return refuse([{ file: null, what: 'the policy authorizes nothing to auto-merge' }]);
459	  }
460	  if (norm.kind === POLICY_ANYTHING) {
461	    return { mergeable: true, why: 'the policy authorizes any diff (the repo\'s delivery settings still apply)', files: [], problems: [] };
462	  }
463	  if (!entries.length) {
464	    return refuse([{ file: null, what: 'this branch changes nothing against the base — there is nothing to merge' }]);
465	  }
466	
467	  const resolveOne = (name) => (name.startsWith(UNDER_PREFIX)
468	    ? underRule(name)
469	    : BUILTIN_MERGE_RULES.get(name) ?? declaredRules.get(name) ?? null);
470	  // An `&&` term is one rule that every part must agree on — for coverage and
471	  // for the whole-diff constraints alike. It deliberately carries no
472	  // `coversMountPolicySources`: that grant belongs to the declared rule that was
473	  // committed with it, never to an expression composed around it.
474	  const resolve = (name) => {
475	    if (!name.includes(CONJUNCTION)) return resolveOne(name);
476	    const parts = name.split(CONJUNCTION).map(resolveOne);
477	    if (parts.some((r) => !r)) return null;
478	    return {
479	      name,
480	      appliesTo: (e) => parts.every((r) => r.appliesTo(e)),
481	      constraint: (covered) => parts.map((r) => r.constraint?.(covered) ?? null).find(Boolean) ?? null,
482	    };
483	  };
484	  const unknown = [...norm.allow, ...norm.reject].filter((n) => n !== POLICY_ANYTHING && !resolve(n));
485	  if (unknown.length) {
486	    const errs = ruleErrors.length ? ` (rule declarations also failed to load: ${ruleErrors.join('; ')})` : '';
487	    return refuse([{ file: null, what: `unresolved rule name(s): ${unknown.join(', ')} — an unknown rule authorizes nothing${errs}` }]);
488	  }
489	
490	  const files = [];
491	  const problems = [];
492	  const coveredBy = new Map(); // allow name -> entries it covered
493	  for (const entry of entries) {
494	    const { file } = entry;
495	    if (POLICY_SOURCES.test(file) && !isCommentOnlyChange(entry)) {
496	      const mountCoverer = VENDORED_MOUNT.test(file)
497	        && norm.allow.find((n) => resolve(n)?.coversMountPolicySources && resolve(n).appliesTo(entry));
498	      if (!mountCoverer) {
499	        files.push({ file, verdict: 'policy-source' });
500	        problems.push({ file, what: `${file} defines auto-merge policy itself — no granular policy may change it` });
501	        continue;
502	      }
503	      // Exempted: it falls through to the ordinary reject/coverage flow below,
504	      // so a reject term still vetoes it and the flagged rule still has to
505	      // cover it on its own terms.
506	    }
507	    const rejectedBy = norm.reject.find((n) => resolve(n).appliesTo(entry));
508	    if (rejectedBy) {
509	      files.push({ file, verdict: `rejected:${rejectedBy}` });
510	      problems.push({ file, what: `${file} matches reject:${rejectedBy}` });
511	      continue;
512	    }
513	    const coverer = norm.allow.find((n) => n === POLICY_ANYTHING || resolve(n).appliesTo(entry));
514	    if (coverer === undefined) {
515	      files.push({ file, verdict: 'uncovered' });
516	      problems.push({ file, what: `${file} (${changeKindOf(entry)} ${classifyPath(entry.file)}) is covered by no allow term` });
517	      continue;
518	    }
519	    files.push({ file, verdict: `covered:${coverer}` });
520	    if (!coveredBy.has(coverer)) coveredBy.set(coverer, []);
521	    coveredBy.get(coverer).push(entry);
522	  }
523	  for (const [name, covered] of coveredBy) {
524	    const failed = resolve(name)?.constraint?.(covered) ?? null;
525	    if (failed) problems.push({ file: null, what: `${name}: ${failed}` });
526	  }
527	
528	  return problems.length
529	    ? refuse(problems, files)
530	    : { mergeable: true, why: `every changed file is covered (${[...coveredBy.keys()].join(', ')})`, files, problems: [] };
531	}
532	
533	// --- the diff against a base ref (shared with narrow-diff.mjs) ----------------
534	
535	// `stderr: ignore` because the ONE expected failure here — `git show` on a path
536	// that does not exist at that ref — is how an added or deleted file answers, and
537	// letting git narrate it once per such file buries the verdict the caller reads.
538	const git = (args, cwd) => execFileSync('git', args, {
539	  cwd, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, stdio: ['ignore', 'pipe', 'ignore'],
540	});
541	
542	// The content of `file` at `ref`, or null when it does not exist there (an added
543	// file) — the same answer a deleted file's "after" gets.
544	function contentAt(ref, file, cwd) {
545	  try {
546	    return git(['show', `${ref}:${file}`], cwd);
547	  } catch {
548	    return null;
549	  }
550	}
551	
552	// The diff this branch carries against `base`, read from the merge base so
553	// commits that landed on the base meanwhile are not counted as this run's work.
554	export function diffEntries({ base, cwd = process.cwd() }) {
555	  // The checkouts these runs work in are shallow, where `merge-base` has no common
556	  // ancestor to find; the base ref itself is then the honest comparison point.
557	  let mergeBase;
558	  try {
559	    mergeBase = git(['merge-base', base, 'HEAD'], cwd).trim();
560	  } catch {
561	    mergeBase = base;
562	  }
563	  const names = git(['diff', '--name-only', mergeBase, 'HEAD'], cwd).split('\n').map((l) => l.trim()).filter(Boolean);
564	  return names.map((file) => ({
565	    file,
566	    before: contentAt(mergeBase, file, cwd),
567	    after: contentAt('HEAD', file, cwd),
568	  }));
569	}
570	
571	// --- the CLI ------------------------------------------------------------------
572	// What the landing lane runs before it may merge:
573	//   node <this file> --base origin/main --policy 'comment-only-changes;readme-changes'
574	// Prints one line per changed file and a final `AUTOMERGE: yes|no — why` verdict
575	// line the worker quotes. Pack-declared rules resolve from the repo's ACTIVE
576	// packs (loaded here, not at import time — discovery re-importing this module
577	// mid-evaluation must find no work started).
578	async function main() {
579	  const argv = process.argv.slice(2);
580	  const at = (flag) => (argv.includes(flag) ? argv[argv.indexOf(flag) + 1] : null);
581	  const cwd = at('--root') ?? process.env.CLAUDE_PROJECT_DIR ?? process.cwd();
582	  const base = at('--base') ?? 'origin/main';
583	  const policy = at('--policy');
584	  if (policy === null) {
585	    console.error('merge-policy: --policy is required (the task\'s automerge, or the item\'s Merge: value)');
586	    process.exitCode = 2;
587	    return;
588	  }
589	
590	  const { loadPacks } = await import('../../engine/pack_loader/pack-registry.mjs');
591	  const { loadConfig } = await import('../../engine/checks/helpers/repo-context.mjs');
592	  const packs = await loadPacks({ localRoot: cwd });
593	  const { rules, errors } = declaredMergeRules(packs, loadConfig(cwd));
594	  for (const e of errors) console.error(`merge-policy: ${e}`);
595	
596	  const entries = diffEntries({ base, cwd });
597	  const verdict = policyVerdict({ policy, entries, declaredRules: rules, ruleErrors: errors });
598	  for (const { file, verdict: v } of verdict.files) console.log(`  ${v.padEnd(32)} ${file}`);
599	  console.log(`\nAUTOMERGE: ${verdict.mergeable ? 'yes' : 'no'} — ${verdict.why}`);
600	}
601	
602	if (import.meta.url === `file://${process.argv[1]}`) {
603	  main().catch((e) => { console.error(`merge-policy: ${e.message}`); process.exitCode = 1; });
604	}
605

