614	    bad('only a PACK record may declare "applyStage" — the engine update flow has no agentic lane (DESIGN §5). '
615	      + 'If the change needs a session on each member, it belongs to the pack whose rules it changes.');
616	  }
617	  if (typeof declared !== 'object' || Array.isArray(declared)) {
618	    bad('"applyStage" must be an object `{ why, instructions }`, not a bare flag — a stage nobody can explain '
