630	#!/usr/bin/env node
631	// Convert task declarations from the retired module form (`tasks/<name>/task.mjs`,
632	// a default-exported object literal) to the data form (`task.json`, pointing at
633	// the task schema through `$schema`), deleting the module once its JSON exists.
634	//
635	// Two callers. The `task-declarations-json` migration record runs this against a
636	// member's OWN local packs on its nightly update, through the registry's io
637	// capabilities, so a member converts without anyone remembering to; and the CLI
638	// below converts a checkout by hand — the canon's own packs, or a member that
639	// wants it done sooner:
640	//
641	//   node engine/migrations/task-declarations-to-json.mjs [--root <repo>] [<task dir>…]
642	//
643	// The module's comments cannot survive in the JSON, so they move to the task's
644	// `README.md`, under one heading, verbatim — mostly they restated the assignment
645	// beside them, but what was rationale is then still where a reader of the task
646	// looks, and the update's apply stage reads it to write the task's `description`.
647	// The conversion prints each block too. A field that is not data (the retired
648	// `precondition()` function) is dropped, and named in the report line: the
649	// contract rejects it either way.
650	
651	import { existsSync, readdirSync, readFileSync, rmSync, writeFileSync, mkdirSync } from 'node:fs';
652	import { dirname, join, relative, posix } from 'node:path';
653	import { pathToFileURL } from 'node:url';
654	
655	export const TASK_JSON = 'task.json';
656	export const TASK_MJS = 'task.mjs';
657	
658	// The schema every converted file points at, in the two-root form: a member reads
659	// it out of its mount, the canon out of its own tree.
660	export const SCHEMA_FILE = 'packs/claudinite-tasks/task.schema.json';
661	export const schemaPath = (exists) => (exists(`.claudinite/shared/${SCHEMA_FILE}`) ? `.claudinite/shared/${SCHEMA_FILE}` : SCHEMA_FILE);
662	
663	// The pack roots a checkout's tasks live under. A member's own are the local
664	// packs; the canon also carries the shared packs at the repo root.
665	export const LOCAL_PACK_ROOT = '.claudinite/local/packs';
666	export const CANON_PACK_ROOT = 'packs';
667	
668	// The order a declaration's keys are written in, grouped by what they say: what
669	// the task is, when it runs, what it may write, then the two phases — code work,
670	// then the agent. A key not listed keeps its place after the listed ones.
671	export const KEY_ORDER = [
672	  '$schema', 'id', 'description',
673	  'frequency', 'schedule_after', 'preconditions',
674	  'expected_outcome', 'automerge', 'on_interrupt', 'invocation_endpoint',
675	  'code_work', 'code_work_timeout', 'code_work_required_secrets',
676	  'agent_model', 'model_from_request', 'agent_instructions', 'agent_execution_timeout',
677	];
678	export function orderTaskKeys(decl) {
679	  const rank = (k) => { const i = KEY_ORDER.indexOf(k); return i === -1 ? KEY_ORDER.length : i; };
680	  return Object.fromEntries(Object.entries(decl).sort(([a], [b]) => rank(a) - rank(b)));
681	}
682	
683	// The JSON text for a declaration object, keys in KEY_ORDER. Returns the keys
684	// that could not be carried (functions, undefined) so the caller can say so.
685	export function serializeTaskDeclaration(decl, schemaRelative) {
686	  const dropped = Object.keys(decl).filter((k) => typeof decl[k] === 'function' || decl[k] === undefined);
687	  const data = Object.fromEntries(Object.entries(decl).filter(([k]) => !dropped.includes(k)));
688	  return { text: `${JSON.stringify(orderTaskKeys({ $schema: schemaRelative, ...data }), null, 2)}\n`, dropped };
689	}
