691	// The comment lines a module carried, for the report: everything outside the
692	// object literal, so a header explaining why the task exists is not lost silently.
693	export function moduleComments(source) {
694	  const out = [];
695	  for (const line of source.split('\n')) {
696	    const whole = /^\s*(\/\/|\/\*|\*\/|\*)\s?(.*)$/.exec(line);
697	    if (whole) { out.push(whole[2]); continue; }
698	    // A trailing `// …` on a field line — the value's own note. A `//` inside a
699	    // string value (a URL) is not one; the field's quote closes before the marker.
700	    const trailing = /^[^'"]*(?:'[^']*'|"[^"]*")?[^'"]*?\s\/\/\s?(.*)$/.exec(line);
701	    if (trailing) out.push(trailing[1]);
702	  }
703	  return out.join('\n').trim();
704	}
