706	// Every `<root>/<pack>/tasks/<task>/` directory under the given pack roots that
707	// carries a task.mjs, repo-relative and posix. `listDir(p)` returns the entry
708	// names of a directory, or null when it is not one.
709	export function taskDirsWithModule(packRoots, { listDir, exists }) {
710	  const out = [];
711	  for (const root of packRoots) {
712	    for (const pack of listDir(root) ?? []) {
713	      const tasks = `${root}/${pack}/tasks`;
714	      for (const task of listDir(tasks) ?? []) {
715	        const dir = `${tasks}/${task}`;
716	        if (exists(`${dir}/${TASK_MJS}`)) out.push(dir);
717	      }
718	    }
719	  }
720	  return out.sort();
721	}
