723	// The section a task's README gains for its module's comments.
724	export const NOTES_HEADING = '## Why the declaration reads as it does';
725	export function readmeWithNotes(existing, id, comments) {
726	  const section = `\n${NOTES_HEADING}\n\nCarried over from the declaration's comments when it became ${TASK_JSON}.\n\n${comments}\n`;
727	  return `${existing ? `${existing.replace(/\n*$/, '\n')}` : `# ${id}\n`}${section}`;
728	}
