730	// Convert the task.mjs in each directory. Capabilities, all repo-relative:
731	//   exists(p), read(p), write(p, text), remove(p), importModule(p) -> module
732	// Returns one report line per directory. A directory already carrying a
733	// task.json keeps it and only loses the module — the JSON is the declaration,
734	// and a second conversion must not clobber an edit made since the first.
735	export async function convertTaskDeclarations(taskDirs, io) {
736	  const schema = schemaPath(io.exists);
737	  const applied = [];
738	  for (const dir of taskDirs) {
739	    const mjs = `${dir}/${TASK_MJS}`;
740	    const json = `${dir}/${TASK_JSON}`;
741	    if (!io.exists(mjs)) continue;
742	    if (io.exists(json)) {
743	      io.remove(mjs);
744	      applied.push(`${mjs}: deleted — ${json} already exists and is the declaration`);
745	      continue;
746	    }
747	    const decl = (await io.importModule(mjs)).default;
748	    if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
749	      applied.push(`${mjs}: not converted — its default export is not a declaration object`);
750	      continue;
751	    }
752	    const comments = moduleComments(io.read(mjs) ?? '');
753	    const { text, dropped } = serializeTaskDeclaration(decl, posix.relative(dir, schema));
754	    io.write(json, text);
755	    io.remove(mjs);
756	    if (comments) {
757	      const readme = `${dir}/README.md`;
758	      io.write(readme, readmeWithNotes(io.read(readme), decl.id ?? dir.slice(dir.lastIndexOf('/') + 1), comments));
759	    }
760	    applied.push(`${mjs} -> ${json}${dropped.length ? ` (dropped non-data field${dropped.length > 1 ? 's' : ''}: ${dropped.join(', ')})` : ''}`
