766	// The io over a real checkout — the same capability names the migration
767	// registry's callers build, so the record and the CLI run one converter.
768	export function checkoutIo(root) {
769	  const abs = (p) => join(root, p);
770	  return {
771	    exists: (p) => existsSync(abs(p)),
772	    read: (p) => (existsSync(abs(p)) ? readFileSync(abs(p), 'utf8') : null),
773	    write: (p, text) => { mkdirSync(dirname(abs(p)), { recursive: true }); writeFileSync(abs(p), text); },
774	    remove: (p) => rmSync(abs(p), { force: true }),
775	    listDir: (p) => { try { return readdirSync(abs(p)); } catch { return null; } },
776	    importModule: (p) => import(pathToFileURL(abs(p)).href),
777	  };
778	}
