1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	// Namespace-imported and guarded for the same reason legacy-shape-in-use is: a
3	// member's pack lane and engine lane converge on separate cycles, and this pack
4	// can sit beside a task-contract that predates either export.
5	import * as contract from '../task-contract.mjs';
6	import * as declarationText from '../task-declaration-text.mjs';
7	
8	// THE ADVISORY HALF OF THE TASK CONTRACT'S FIELD TOLERANCES. `normalizeTaskDeclaration`
9	// accepts two generations of field names and the retired one-word outcome
10	// ceilings, so a task declared in the oldest vocabulary runs exactly like one
11	// declared today — and nothing told its author that the acceptance ends a week
12	// after this advisory ships (#1642).
13	//
14	// It reads the declaration SOURCE rather than the normalized object, because by
15	// the time anything holds a task declaration the legacy spelling is gone: the
16	// door normalizes at load, which is what makes the tolerance invisible.
17	// Matching is therefore textual and deliberately conservative — a top-level key
18	// line in a task declaration — so the finding always points at a line an author
19	// can edit. Both declaration forms are read, and one pattern covers both: the
20	// key is bare in the module form and quoted in the JSON, and the value quote is
21	// whichever that file uses.
22	//
23	// ADVISORY: the old spelling works, and a task file is a member's own content.
24	const TASK_FILE = /(^|\/)tasks\/[^/]+\/task\.(json|mjs)$/;
25	const isTaskFile = (path) =>
