1	// Where a task's declaration lives and how it is loaded — the one place that
2	// knows a task folder may spell its declaration two ways (task-declaration-text.mjs
3	// says which two and why). Everything that resolves a declaration — discovery, the
4	// dispatch validators, the checks that gate on a task folder — goes through the
5	// names here, so the retirement of the module form is one edit in one file.
6	
7	import { existsSync, readFileSync } from 'node:fs';
8	import { dirname, join } from 'node:path';
9	import { TASK_DECLARATION_FILE, parseTaskDeclaration } from './task-declaration-text.mjs';
10	
11	export * from './task-declaration-text.mjs';
12	
13	// The declaration file a task directory carries, or null when it carries none.
14	export function findTaskDeclaration(taskDir) {
15	  return existsSync(join(taskDir, TASK_DECLARATION_FILE)) ? join(taskDir, TASK_DECLARATION_FILE) : null;
16	}
17	
18	// The declaration's raw object, before normalization. A file that does not
19	// parse throws with its own message — the callers turn that into a per-task
20	// error, never a sunk scan.
21	export async function loadTaskDeclaration(file) {
22	  return parseTaskDeclaration(readFileSync(file, 'utf8'));
23	}
24	
25	// The declaration file a `.../tasks/<name>/task.md` path's folder carries, given
26	// only an `exists` capability over repo-relative paths (the dispatch validator's
27	// world).
28	export function siblingTaskDeclaration(taskMdPath, exists) {
29	  const file = `${dirname(taskMdPath)}/${TASK_DECLARATION_FILE}`;
30	  return exists(file) ? file : null;
31	}
