    has: (key) => at(key).test(code),
    str: (key) => {
      const m = new RegExp(`(?:^|[{,])\\s*${key}:\\s*['"]([^'"]+)['"]`, 'm').exec(code);
      return m ? m[1] : null;
    },
  };
}

