1	#!/usr/bin/env node
2	// Perform every declared migration's write side in a checkout:
3	//   - file aliases  — "prefer Y, fall back to X, and rename X -> Y"
4	//   - materialize   — vendor pack templates into the repo's own tree
5	//   - rewrite       — repoint refs in place (idempotent literal replacements)
6	//   - declarePacks  — declare a pack (and its config) the member does not carry yet
7	//   - normalizeLocalDeclarations — rewrite local-pack declarations to `local/<id>`
8	//   - taskDeclarationsToJson — convert local-pack task.mjs declarations to task.json
9	// Idempotent: a no-op once everything has been applied. Dependency-free.
10	//
11	// Two roots. The DEST is the repo being healed (CLAUDE_PROJECT_DIR / cwd). The
12	// TEMPLATE source is the corpus that ships the migrations — the root this module
13	// sits two levels under (engine/migrations/): in the canon repo that's the repo
14	// root; in a consumer that mounts Claudinite at .claudinite/shared/, it's that
15	// mount root (so a template path like packs/…/stubs/foo.yml resolves against the
16	// mounted pack, while its dest lands in the consumer's own .github/). The two
17	// coincide in the canon repo.
18	//
19	// Runs against a local checkout (a session, CI, or a future SessionStart
20	// self-heal hook wired via bootstrap). Each member migrates ITSELF: the update flows
21	// runs this applier from the fresh canon clone it fetched, so even a dormant
22	// project catches up on every record ever landed — there is no fleet-wide
23	// apply pass and no retirement; the records simply accumulate.
24	import { existsSync, renameSync, mkdirSync, readFileSync, writeFileSync, readdirSync, rmSync } from 'node:fs';
25	import { dirname, join } from 'node:path';
26	import { fileURLToPath, pathToFileURL } from 'node:url';
27	import { loadMigrations, applyMigration } from './registry.mjs';
28	
29	export async function main() {
30	  const repoRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
31	  const canonRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url)))); // <corpus>/engine/migrations/
32	  const migrations = await loadMigrations();
33	
34	  const exists = (p) => existsSync(join(repoRoot, p));
35	  const read = (p) => (existsSync(join(repoRoot, p)) ? readFileSync(join(repoRoot, p), 'utf8') : null);
36	  const write = (p, c) => {
37	    mkdirSync(dirname(join(repoRoot, p)), { recursive: true });
38	    writeFileSync(join(repoRoot, p), c);
39	  };
40	  const move = (from, to) => {
41	    mkdirSync(dirname(join(repoRoot, to)), { recursive: true });
42	    renameSync(join(repoRoot, from), join(repoRoot, to));
43	  };
44	  const readTemplate = (p) => (existsSync(join(canonRoot, p)) ? readFileSync(join(canonRoot, p), 'utf8') : null);
45	  const listDir = (p) => { try { return readdirSync(join(repoRoot, p)); } catch { return null; } };
46	  const remove = (p) => rmSync(join(repoRoot, p), { force: true });
47	  const importModule = (p) => import(pathToFileURL(join(repoRoot, p)).href);
48	
49	  const applied = [];
50	  for (const m of migrations) applied.push(...(await applyMigration(m, { exists, move, read, write, readTemplate, listDir, remove, importModule })));
51	  if (applied.length) console.log(`Applied migrations:\n${applied.map((x) => `  ${x}`).join('\n')}`);
52	}
53	
54	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
55	if (isMain) {
56	  main().catch((e) => { console.error(`migrations apply failed: ${e.message}`); process.exit(1); });
57	}
58

