const owesDelivery = new Set();
let owedBy = null;
const write = (p, c) => {
  if (!p.startsWith(WORKFLOW_DIR)) return put(p, c);
  put(stagedAt(p), c);
  if (!withheld.includes(p)) withheld.push(p);
  if (owedBy) owesDelivery.add(owedBy);
