1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { makeRepo, cleanup } from '../../../engine-tests/helpers.mjs';
4	import { discoverTasks } from '../discover.mjs';
5	
6	const packMjs = (id) => `export default { id: '${id}' };\n`;
7	const taskJson = (id, over = {}) => `${JSON.stringify({ id, frequency: 'daily', expected_outcome: 'no_code_changes', ...over })}\n`;
8	// The retired module form, which still loads (task-declaration.mjs).
9	const taskMjs = (id, over = {}) => {
10	  const d = { id, frequency: 'daily', preconditions: ['none'], agent_model: 'sonnet', expected_outcome: 'no_code_changes', agent_instructions: 'task.md', agent_execution_timeout: 900, ...over };
11	  const fields = Object.entries(d).map(([k, v]) => `${k}: ${JSON.stringify(v)}`).join(', ');
12	  return `export default { ${fields} };\n`;
13	};
14	
15	test('discoverTasks finds a declared local pack\'s tasks with the repo-relative task path', async () => {
16	  const root = makeRepo({ changed: {
17	    '.claudinite/local/packs/mypack/pack.mjs': packMjs('mypack'),
18	    '.claudinite/local/packs/mypack/tasks/alpha/task.mjs': taskMjs('alpha', { frequency: 'daily', agent_model: 'opus', expected_outcome: 'fresh_pr', automerge: 'anything' }),
19	    '.claudinite/local/packs/mypack/tasks/alpha/task.md': '# alpha worker\n',
20	    '.claudinite/local/packs/mypack/tasks/beta/task.mjs': taskMjs('beta', { frequency: 'weekly' }),
21	    '.claudinite/local/packs/mypack/tasks/beta/task.md': '# beta worker\n',
22	  } });
23	  try {
24	    const { tasks, errors } = await discoverTasks(root, { packs: ['local/mypack'] });
25	    assert.deepEqual(errors, []);
26	    const byId = Object.fromEntries(tasks.map((t) => [t.id, t]));
27	    assert.deepEqual(Object.keys(byId).sort(), ['alpha', 'beta']);
28	    assert.equal(byId.alpha.pack, 'mypack');
29	    assert.equal(byId.alpha.taskPath, '.claudinite/local/packs/mypack/tasks/alpha/task.md');
30	    // The door: a retired spelling is normalized where the declaration is LOADED, so nothing
31	    // downstream ever sees it (DESIGN §17.1).
32	    assert.equal(byId.alpha.decl.frequency, 'daily');
33	    assert.equal(byId.beta.decl.frequency, 'weekly');
34	  } finally { cleanup(root); }
35	});
36	
37	test('discoverTasks skips tasks of an undeclared (inactive) pack', async () => {
38	  const root = makeRepo({ changed: {
39	    '.claudinite/local/packs/mypack/pack.mjs': packMjs('mypack'),
40	    '.claudinite/local/packs/mypack/tasks/alpha/task.mjs': taskMjs('alpha'),
41	    '.claudinite/local/packs/mypack/tasks/alpha/task.md': '# w\n',
42	  } });
43	  try {
44	    const { tasks } = await discoverTasks(root, { packs: [] }); // pack not declared
45	    assert.deepEqual(tasks, []);
46	  } finally { cleanup(root); }
47	});
48	
49	test('discoverTasks reports a malformed declaration and a dir/id mismatch as errors, not tasks', async () => {
50	  const root = makeRepo({ changed: {
51	    '.claudinite/local/packs/mypack/pack.mjs': packMjs('mypack'),
52	    // bad frequency
53	    '.claudinite/local/packs/mypack/tasks/bad/task.mjs': taskMjs('bad', { frequency: 'nightly' }),
54	    '.claudinite/local/packs/mypack/tasks/bad/task.md': '# w\n',
55	    // dir name != declared id
56	    '.claudinite/local/packs/mypack/tasks/mismatch/task.mjs': taskMjs('other'),
57	    '.claudinite/local/packs/mypack/tasks/mismatch/task.md': '# w\n',
58	  } });
59	  try {
60	    const { tasks, errors } = await discoverTasks(root, { packs: ['local/mypack'] });
61	    assert.deepEqual(tasks, []);
