9	
10	// The printed `dispatch:` field is the executor's whole contract with this shell
11	// — the agent branches on the verdict, not on the prose beside it — and the exit
12	// code answers the narrower question the owner set on 2026-08-14: ZERO whenever
13	// the routine goes on, including when going on means stopping on purpose, and
14	// non-zero ONLY when it stops unexpectedly. So these tests drive the REAL CLI in
15	// a child process and assert BOTH: the verdict by name, and the literal code.
16	// The codes stay written literal (0/2/12/15) rather than imported from the
17	// module on purpose: importing the constants would let a renumbering pass green.
18	const PACK = join(dirname(fileURLToPath(import.meta.url)), '..');
19	const ENGINE = join(PACK, '..', '..', 'engine');
20	const SHELL = join(PACK, 'resolve-dispatch.mjs');
21	
22	const OK = 0, USAGE = 2, NO_TRIGGER = 12, SCOPE_MISMATCH = 15;
23	
24	const taskMjs = (id) => `export default {
25	  id: ${JSON.stringify(id)},
26	  frequency: 'daily',
27	  preconditions: ['none'],
28	  agent_model: 'sonnet',
29	  expected_outcome: 'fresh_pr',
30	  automerge: 'nothing',
31	  agent_instructions: 'task.md',
32	  agent_execution_timeout: 1800,
33	};
34	`;
35	
36	// A scratch checkout shaped like the real thing: a declared pack carrying a
37	// well-formed task, plus an UNDECLARED pack carrying an equally well-formed one
38	// (so "pack not declared" is isolated from every other failure mode).
39	function fixtureRepo() {
40	  const root = mkdtempSync(join(tmpdir(), 'claudinite-dispatch-'));
41	  writeFiles(root, {
42	    '.claudinite-settings.json': JSON.stringify({ packs: ['demo'] }),
43	    'packs/demo/tasks/demo-task/task.md': '# demo task\n',
44	    'packs/demo/tasks/demo-task/task.mjs': taskMjs('demo-task'),
45	    'packs/undeclared/tasks/rogue-task/task.md': '# rogue task\n',
46	    'packs/undeclared/tasks/rogue-task/task.mjs': taskMjs('rogue-task'),
47	  });
48	  return root;
49	}
50	
51	const GOOD_PATH = 'packs/demo/tasks/demo-task/task.md';
