  console.log(JSON.stringify(out, null, 2));
});
"
git stash pop

git stash && timeout 120 node --experimental-vm-modules -e "
import('./vendoring/rehearsal/fixtures.mjs').then(async ({FIXTURES, MODES}) => {
  const { rehearse, formatResult } = await import('./vendoring/rehearsal/rehearse.mjs');
  const fixture = FIXTURES.find(f => f.name === 'legacy-task');
  const mode = MODES.find(m => m.name === 'fresh') || MODES[0];
  const r = rehearse(fixture, mode);
  console.log(formatResult(r));
});
" 2>&1 | tail -60
git stash pop

